def page(fn,title,sub,qs,note):
    out=[]
    for i,(stem,opts,ans,why,sure) in enumerate(qs,1):
        ob=''.join(f'<button class="opt">{chr(65+j)}. {E(o)}</button>' for j,o in enumerate(opts))
        fl='' if sure else '<div class="flag">⚠️ Not 100% sure. See note.</div>'
        out.append(f'<div class="q" data-a="{json.dumps(ans)}" data-m="0"><h3><span>Q{i}</span>{E(stem)}</h3>{ob}<div class="why">✅ <b>{", ".join(chr(65+a) for a in ans)}</b>{" · "+E(why) if why else ""}{fl}</div></div>')
    open(fn,'w').write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><style>{CSS}</style></head><body><div class="wrap"><a class="back" href="systems-lec-exam3.html?v={V}">← Back to Exam 3</a><div class="hero"><h1>{E(title)}</h1><p>{E(sub)}</p></div><div class="note">{note}</div><div class="bar"><button id="shuf">🎲 Shuffle</button><button id="miss">🔁 Misses only</button><button id="all">↺ Show all</button><span class="score" id="sc"></span></div><div id="qs">{"".join(out)}</div></div><script>{JS}</script></body></html>')
page('systems-lec3-old2024.html','📝 Poole Old Exam · 2024','Oct 25, 2024 · 22 questions × 4 pts = 88 · highlighted key from the posted exam',P2024,'Tap an answer to check it. Answers = the <b>posted 2024 key</b> (all checked against the lectures/math). Calculator allowed.')
